        tracing::error!(%error, "switchboard server stopped");
    }
}

async fn shutdown_signal(state: api::AppState) {
    #[cfg(unix)]
    {
        let mut terminate =
            tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
                .expect("install SIGTERM handler");
