// `CallLifecycle` is intentionally not Clone. Refreshing a projection needs a
// snapshot, not a second lifecycle owner.
trait RefreshClone {
    fn clone_for_refresh(&self) -> CallLifecycle;
}
impl RefreshClone for CallLifecycle {
    fn clone_for_refresh(&self) -> CallLifecycle {
        CallLifecycle {
            route: self.route.clone(),
            project: self.project.clone(),
            persistent_session_id: self.persistent_session_id.clone(),
            leg: self.leg.clone(),
            phase: self.phase,
            model: self.model.clone(),
            thinking_requested: self.thinking_requested.clone(),
            thinking_effective: self.thinking_effective.clone(),
            last_activity: self.last_activity,
            operation: self.operation.clone(),
            terminal_reason: self.terminal_reason.clone(),
            candidate: None,
            catalog: self.catalog.clone(),
            status_value: self.status_value.clone(),
        }
    }
}

